begin;
set local app.auvo_sync_write='true';
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public;
select plan(9);
select has_function('pcm','sso_listar_listas_materiais_mediada',array['uuid','uuid','integer','uuid'],'listagem mediada existe');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values ('17995000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','s179-listar@test.local',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values ('17995000-0000-4000-8000-000000000001','superadmin','Gestor sintético',true);
insert into pcm.clientes(id,nome,created_by) values ('17995000-0000-4000-8000-000000000002','Cliente A','17995000-0000-4000-8000-000000000001'),('17995000-0000-4000-8000-000000000003','Cliente B','17995000-0000-4000-8000-000000000001');
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values ('17995000-0000-4000-8000-000000000001','material.gerir','17995000-0000-4000-8000-000000000002');
insert into pcm.ordens_servico(id,client_id,numero,titulo,categoria,created_by) values ('17995000-0000-4000-8000-000000000011','17995000-0000-4000-8000-000000000002','S179-LIST-A','OS A','corretiva','17995000-0000-4000-8000-000000000001'),('17995000-0000-4000-8000-000000000012','17995000-0000-4000-8000-000000000003','S179-LIST-B','OS B','corretiva','17995000-0000-4000-8000-000000000001');
insert into pcm.listas_materiais(id,cliente_id,ordem_servico_id,responsavel,texto_original,criado_por) values ('17995000-0000-4000-8000-000000000021','17995000-0000-4000-8000-000000000002','17995000-0000-4000-8000-000000000011','cliente','Material A','17995000-0000-4000-8000-000000000001'),('17995000-0000-4000-8000-000000000022','17995000-0000-4000-8000-000000000002','17995000-0000-4000-8000-000000000011','sinergica','Material A2','17995000-0000-4000-8000-000000000001'),('17995000-0000-4000-8000-000000000023','17995000-0000-4000-8000-000000000003','17995000-0000-4000-8000-000000000012','cliente','Material B','17995000-0000-4000-8000-000000000001');
set local request.jwt.claims='{"sub":"17995000-0000-4000-8000-000000000001","role":"authenticated","user_role":"superadmin"}';
set local role authenticated;
select throws_ok($$select * from pcm.sso_listar_listas_materiais_mediada('17995000-0000-4000-8000-000000000002','17995000-0000-4000-8000-000000000011',1,null)$$,'55000','listagem_materiais_bloqueada','gate fechado impede consulta');
reset role;
update pcm.sso_listagem_materiais_mediada_gate set habilitado=true where id;
set local role authenticated;
select is((select texto_original from pcm.sso_listar_listas_materiais_mediada('17995000-0000-4000-8000-000000000002','17995000-0000-4000-8000-000000000011',1,null)),'Material A','primeira página correta');
select is((select texto_original from pcm.sso_listar_listas_materiais_mediada('17995000-0000-4000-8000-000000000002','17995000-0000-4000-8000-000000000011',1,'17995000-0000-4000-8000-000000000021')),'Material A2','cursor devolve página seguinte');
select throws_ok($$select * from pcm.sso_listar_listas_materiais_mediada('17995000-0000-4000-8000-000000000002','17995000-0000-4000-8000-000000000012',20,null)$$,'42501','ordem_nao_encontrada_ou_sem_acesso','OS de outro Cliente recusada');
select throws_ok($$select * from pcm.sso_listar_listas_materiais_mediada('17995000-0000-4000-8000-000000000003','17995000-0000-4000-8000-000000000012',20,null)$$,'42501','ordem_nao_encontrada_ou_sem_acesso','Cliente sem concessão recusado');
select throws_ok($$select * from pcm.sso_listar_listas_materiais_mediada('17995000-0000-4000-8000-000000000002','17995000-0000-4000-8000-000000000011',101,null)$$,'22023','parametros_invalidos','limite inválido recusado');
reset role;
select ok(has_function_privilege('authenticated','pcm.sso_listar_listas_materiais_mediada(uuid,uuid,integer,uuid)','execute') and not has_function_privilege('authenticated','pcm.sso_listar_listas_materiais(uuid,uuid,integer,uuid)','execute') and not has_function_privilege('anon','pcm.sso_listar_listas_materiais_mediada(uuid,uuid,integer,uuid)','execute'),'mediadora autenticada e núcleo privado');
update config.sso_concessoes set ativa=false where usuario_id='17995000-0000-4000-8000-000000000001' and acao='material.gerir';
set local role authenticated;
select throws_ok($$select * from pcm.sso_listar_listas_materiais_mediada('17995000-0000-4000-8000-000000000002','17995000-0000-4000-8000-000000000011',20,null)$$,'42501','ordem_nao_encontrada_ou_sem_acesso','revogação sequencial impede leitura');
reset role;
select * from finish();
rollback;
